import Foundation

/// Serial executor backed by a single dedicated thread, so every Java call
/// runs on one stable, JNI-attached thread. JNI environments are thread-bound;
/// the wrappers generated by swift-java capture the environment of the thread
/// they were created on.
final class JavaThreadExecutor: SerialExecutor, @unchecked Sendable {

	private let condition = NSCondition()
	private var jobs: [UnownedJob] = []

	init() {
		let thread = Thread { [self] in run() }
		thread.name = "vfs-fskit-java"
		thread.start()
	}

	func enqueue(_ job: consuming ExecutorJob) {
		let unownedJob = UnownedJob(job)
		condition.lock()
		jobs.append(unownedJob)
		condition.signal()
		condition.unlock()
	}

	func asUnownedSerialExecutor() -> UnownedSerialExecutor {
		UnownedSerialExecutor(ordinary: self)
	}

	private func run() {
		while true {
			condition.lock()
			while jobs.isEmpty {
				condition.wait()
			}
			let job = jobs.removeFirst()
			condition.unlock()
			job.runSynchronously(on: asUnownedSerialExecutor())
		}
	}
}
